import { buildAdoptVaultAuthorityInstruction, buildClaimInstruction, buildInitializeSaleInstruction, buildLifecycleInstruction, buildPurchaseInstruction, buildSetPausedInstruction, buildUpdateTimingInstruction } from "./instructions.js";
export function buildSaleActivationOperations(input) { const init = buildInitializeSaleInstruction(input); const adopt = buildAdoptVaultAuthorityInstruction({ programId: input.programId, salePda: init.salePda.toBase58(), currentVaultAuthority: input.sourceVaultAuthority, sourceVaultTokenAccount: input.sourceVaultTokenAccount }); return [{ name: "initialize-sale", instruction: init.instruction, salePda: init.salePda.toBase58(), vaultAuthorityPda: init.vaultAuthorityPda.toBase58() }, { name: "adopt-vault-authority", instruction: adopt.instruction, salePda: init.salePda.toBase58(), vaultAuthorityPda: adopt.vaultAuthorityPda.toBase58() }]; }
export function buildPurchaseOperation(input) { const result = buildPurchaseInstruction(input); return { name: "purchase", instruction: result.instruction, salePda: input.salePda, participantPda: result.participantPda.toBase58(), vaultAuthorityPda: result.vaultAuthorityPda.toBase58() }; }
export function buildClaimOperation(input) { const result = buildClaimInstruction(input); return { name: "claim", instruction: result.instruction, salePda: input.salePda, participantPda: result.participantPda.toBase58(), vaultAuthorityPda: result.vaultAuthorityPda.toBase58() }; }
export function buildLifecycleOperation(input) { return { name: input.action, instruction: buildLifecycleInstruction(input), salePda: input.salePda }; }
export function buildPauseOperation(input) { return { name: input.paused ? "pause" : "resume", instruction: buildSetPausedInstruction(input), salePda: input.salePda }; }
export function buildTimingOperation(input) { return { name: "update-timing", instruction: buildUpdateTimingInstruction(input), salePda: input.salePda }; }
